def transform(grid):
    g=[row[:] for row in grid]
    p7=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==7]
    p9=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==9]
    r7=[r for r,c in p7]; c7=[c for r,c in p7]
    r9=[r for r,c in p9]; c9=[c for r,c in p9]
    a=(min(r7),max(r7),min(c7),max(c7)); b=(min(r9),max(r9),min(c9),max(c9))
    if len(p7)==1:
        for r,c in p7: g[r][c]=6
    for r,c in p9: g[r][c]=7
    if a[0]==b[0] and a[1]==b[1]:
        lo,hi=sorted((a[2],b[2]))
        for r in range(b[0],b[1]+1):
            for c in range(lo,hi+1):
                if grid[r][c]==0: g[r][c]=2
    else:
        lo,hi=sorted((a[0],b[0]))
        for r in range(lo,hi+1):
            for c in range(b[2],b[3]+1):
                if grid[r][c]==0 or (len(p7)==1 and len(p9)==1 and grid[r][c]==6 and any(grid[r][cc]==0 for cc in range(len(grid[0])))): g[r][c]=2
    return g
